def latestTimeByReplacingQuestionMarks(s: str) -> str:
    s_list = list(s)

    # Handle HH:
    # First digit of HH
    if s_list[0] == '?':
        # If the second digit is '0' or '1', the first digit can be '1'.
        # If the second digit is '2'-'9', the first digit must be '0'.
        # If the second digit is '?', it can be '1'.
        if s_list[1] == '?' or '0' <= s_list[1] <= '1':
            s_list[0] = '1'
        else:
            s_list[0] = '0'

    # Second digit of HH
    if s_list[1] == '?':
        # If the first digit is '1', the second digit can be '1' (max 11).
        # If the first digit is '0', the second digit can be '9' (max 09).
        if s_list[0] == '1':
            s_list[1] = '1'
        else:
            s_list[1] = '9'

    # Handle MM:
    # First digit of MM
    if s_list[3] == '?':
        # Max value for tens place of minutes is '5'.
        s_list[3] = '5'

    # Second digit of MM
    if s_list[4] == '?':
        # Max value for units place of minutes is '9'.
        s_list[4] = '9'

    return "".join(s_list)
