import sys

def solve():
    # Read N from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    cuboids = []
    ptr = 1
    for i in range(N):
        x1 = int(input_data[ptr])
        y1 = int(input_data[ptr+1])
        z1 = int(input_data[ptr+2])
        x2 = int(input_data[ptr+3])
        y2 = int(input_data[ptr+4])
        z2 = int(input_data[ptr+5])
        cuboids.append((x1, y1, z1, x2, y2, z2))
        ptr += 6

    # Since constraints on coordinates are small (0-100), 
    # we can use a 3D grid to mark which cuboid occupies which unit volume cell.
    # grid[x][y][z] will store the index of the cuboid (1-indexed) occupying the cell.
    grid = [[[0] * 100 for _ in range(100)] for _ in range(100)]

    for i in range(N):
        x1, y1, z1, x2, y2, z2 = cuboids[i]
        for x in range(x1, x2):
            for y in range(y1, y2):
                for z in range(z1, z2):
                    grid[x][y][z] = i + 1

    # To store neighbors for each cuboid
    # Using a set to avoid counting the same neighbor multiple times
    neighbors = [set() for _ in range(N)]

    # Check for sharing faces along X, Y, and Z directions
    for x in range(100):
        for y in range(100):
            for z in range(100):
                id1 = grid[x][y][z]
                if id1 == 0:
                    continue

                # Check X-direction neighbor
                if x + 1 < 100:
                    id2 = grid[x+1][y][z]
                    if id2 != 0 and id1 != id2:
                        neighbors[id1-1].add(id2)
                        neighbors[id2-1].add(id1)

                # Check Y-direction neighbor
                if y + 1 < 100:
                    id2 = grid[x][y+1][z]
                    if id2 != 0 and id1 != id2:
                        neighbors[id1-1].add(id2)
                        neighbors[id2-1].add(id1)

                # Check Z-direction neighbor
                if z + 1 < 100:
                    id2 = grid[x][y][z+1]
                    if id2 != 0 and id1 != id2:
                        neighbors[id1-1].add(id2)
                        neighbors[id2-1].add(id1)

    # Output the count of unique neighbors for each cuboid
    for i in range(N):
        print(len(neighbors[i]))

if __name__ == "__main__":
    solve()
