import sys

def rotate_90(shape):
    """Rotates a 4x4 shape 90 degrees clockwise."""
    new_shape = [['.' for _ in range(4)] for _ in range(4)]
    for r in range(4):
        for c in range(4):
            new_shape[c][3-r] = shape[r][c]
    return new_shape

def get_normalized_coords(shape):
    """Returns the coordinates of '#' relative to the top-leftmost '#'."""
    coords = []
    for r in range(4):
        for c in range(4):
            if shape[r][c] == '#':
                coords.append((r, c))
    if not coords:
        return []
    min_r = min(r for r, c in coords)
    min_c = min(c for r, c in coords if r == min_r)
    return sorted([(r - min_r, c - min_c) for r, c in coords])

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    polyominoes_raw = []
    for i in range(0, 12, 4):
        grid = [list(row) for row in input_data[i:i+4]]
        polyominoes_raw.append(grid)

    # Pre-calculate all 4 rotations for each polyomino
    all_rotations = []
    for shape in polyominoes_raw:
        rotations = []
        curr = shape
        for _ in range(4):
            rotations.append(get_normalized_coords(curr))
            curr = rotate_90(curr)
        # Remove duplicate rotations (e.g., for a square)
        unique_rots = []
        for r in rotations:
            if r not in unique_rots:
                unique_rots.append(r)
        all_rotations.append(unique_rots)

    # Check total number of '#' cells first
    total_cells = sum(row.count('#') for p in polyominoes_raw for row in p)
    if total_cells != 16:
        print("No")
        return

    def can_place(grid, coords, dr, dc):
        for r, c in coords:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < 4 and 0 <= nc < 4) or grid[nr][nc]:
                return False
        return True

    def place(grid, coords, dr, dc, val):
        for r, c in coords:
            grid[r + dr][c + dc] = val

    def backtrack(poly_idx, grid):
        if poly_idx == 3:
            return True

        # Try every rotation of the current polyomino
        for rot_coords in all_rotations[poly_idx]:
            # Try every possible translation on the 4x4 grid
            for dr in range(-4, 4):
                for dc in range(-4, 4):
                    if can_place(grid, rot_coords, dr, dc):
                        place(grid, rot_coords, dr, dc, True)
                        if backtrack(poly_idx + 1, grid):
                            return True
                        place(grid, rot_coords, dr, dc, False)
        return False

    # Initial empty grid
    grid = [[False for _ in range(4)] for _ in range(4)]
    if backtrack(0, grid):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

```

