import sys

def solve():
    # Read input from stdin
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return

        s = input_data[0]
        t = input_data[1]
    except EOFError:
        return

    # The vertices of a regular pentagon can be represented as indices 0-4
    # Let A=0, B=1, C=2, D=3, E=4
    mapping = {'A': 0, 'B': 1, 'C': 2, 'D': 3, 'E': 4}

    # Get the indices for the two segments
    s1, s2 = mapping[s[0]], mapping[s[1]]
    t1, t2 = mapping[t[0]], mapping[t[1]]

    # In a regular pentagon, the length of a segment between two vertices
    # depends only on the distance between their indices modulo 5.
    # The distance can be |i - j| or 5 - |i - j|.
    # This distance is either 1 (side) or 2 (diagonal).

    def get_dist(p1, p2):
        diff = abs(p1 - p2)
        return min(diff, 5 - diff)

    if get_dist(s1, s2) == get_dist(t1, t2):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
```

