import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Initialize distance matrix for Floyd-Warshall
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = w
        idx += 3

    # Floyd-Warshall to find all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF: continue
            for j in range(N):
                if dist[k][j] < INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # DP state: dp[mask][last_vertex]
    # mask: bitmask of visited vertices
    # last_vertex: the current vertex we are at
    dp = [[INF] * N for _ in range(1 << N)]

    # Base case: start at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Transition: from current state (mask, i), move to vertex j
    for mask in range(1, 1 << N):
        for i in range(N):
            if dp[mask][i] == INF:
                continue

            # Try to visit vertex j
            for j in range(N):
                if dist[i][j] == INF:
                    continue

                new_mask = mask | (1 << j)
                new_dist = dp[mask][i] + dist[i][j]
                if dp[new_mask][j] > new_dist:
                    dp[new_mask][j] = new_dist

    # The answer is the minimum weight among all paths that visit all vertices
    full_mask = (1 << N) - 1
    ans = min(dp[full_mask])

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
```

