def smallestString(s: str) -> str:
    n = len(s)
    s_list = list(s)

    # Find the first character that is not 'a' to start the operation
    start = -1
    for i in range(n):
        if s_list[i] != 'a':
            start = i
            break

    # If the string consists only of 'a's, we must perform one operation.
    # The lexicographically smallest result is changing the last 'a' to 'z'.
    if start == -1:
        s_list[-1] = 'z'
        return "".join(s_list)

    # Start shifting from the first non-'a' character
    # Stop shifting when we encounter another 'a' or reach the end of the string
    for i in range(start, n):
        if s_list[i] == 'a':
            break
        # Shift character to the previous one: 'b' -> 'a', ..., 'z' -> 'y'
        s_list[i] = chr(ord(s_list[i]) - 1)

    return "".join(s_list)
