import sys

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = [list(row) for row in input_data[2:]]

    # exists[i][j] is True if cookie at (i, j) is still there
    exists = [[True for _ in range(W)] for _ in range(H)]

    # Keep track of how many cookies are in each row/column and their colors
    # row_counts[i][color] = number of cookies of that color in row i
    row_counts = [{} for _ in range(H)]
    col_counts = [{} for _ in range(W)]

    for i in range(H):
        for j in range(W):
            color = grid[i][j]
            row_counts[i][color] = row_counts[i].get(color, 0) + 1
            col_counts[j][color] = col_counts[j].get(color, 0) + 1

    # Queues for rows and columns that might be fully removable
    # A row/column is a candidate if it has >= 2 cookies and all are same color
    row_candidates = set(range(H))
    col_candidates = set(range(W))

    while True:
        to_remove = []

        # Check rows
        rows_to_process = list(row_candidates)
        row_candidates.clear()
        for i in rows_to_process:
            # Count total existing cookies in this row
            total_in_row = sum(row_counts[i].values())
            if total_in_row >= 2:
                # Check if all existing are same color (only one key in dict)
                if len(row_counts[i]) == 1:
                    to_remove.append(('r', i))

        # Check columns
        cols_to_process = list(col_candidates)
        col_candidates.clear()
        for j in cols_to_process:
            total_in_col = sum(col_counts[j].values())
            if total_in_col >= 2:
                if len(col_counts[j]) == 1:
                    to_remove.append(('c', j))

        if not to_remove:
            break

        # Mark for removal to avoid order-of-removal bias within one step
        actual_removal_coords = []
        for type, idx in to_remove:
            if type == 'r':
                for j in range(W):
                    if exists[i := idx][j]:
                        actual_removal_coords.append((i, j))
            else:
                for i in range(H):
                    if exists[i][j := idx]:
                        actual_removal_coords.append((i, j))

        # To handle the logic "remove them all and return to 1" correctly:
        # The prompt implies we check rows, then check columns, THEN remove.
        # Let's refine the removal logic to strictly follow the 1->2->3 sequence.

        # We need to find which cells are marked by either row or col operations
        marked = [[False for _ in range(W)] for _ in range(H)]
        any_marked = False

        # Step 1: Mark Rows
        for i in range(H):
            total = sum(row_counts[i].values())
            if total >= 2 and len(row_counts[i]) == 1:
                any_marked = True
                for j in range(W):
                    if exists[i][j]: marked[i][j] = True

        # Step 2: Mark Cols
        for j in range(W):
            total = sum(col_counts[j].values())
            if total >= 2 and len(col_counts[j]) == 1:
                any_marked = True
                for i in range(H):
                    if exists[i][j]: marked[i][j] = True

        if not any_marked:
            break

        # Step 3: Remove and update counts
        for i in range(H):
            for j in range(W):
                if marked[i][j]:
                    exists[i][j] = False
                    color = grid[i][j]
                    row_counts[i][color] -= 1
                    if row_counts[i][color] == 0:
                        del row_counts[i][color]
                    col_counts[j][color] -= 1
                    if col_counts[j][color] == 0:
                        del col_counts[j][color]

        # After removal, all rows and columns could potentially be candidates again
        row_candidates = set(range(H))
        col_candidates = set(range(W))

    # Final count
    ans = 0
    for i in range(H):
        for j in range(W):
            if exists[i][j]:
                ans += 1
    print(ans)

if __name__ == "__main__":
    solve()
