def minLength(s: str) -> int:
    stack = []
    for char in s:
        if stack:
            # Check if the top of the stack and current char form "AB" or "CD"
            if (stack[-1] == 'A' and char == 'B') or (stack[-1] == 'C' and char == 'D'):
                stack.pop()
                continue
        stack.append(char)
    return len(stack)
