    # Read input from stdin and strip whitespace
    s = sys.stdin.read().strip()
    if not s:
        return

    # An Extended ABC string must match the regular expression A*B*C*
    # We can check this by iterating through the string and ensuring
    # that once we move from A to B, we never see A again,
    # and once we move to C, we never see A or B again.

    current_stage = 0  # 0: A's, 1: B's, 2: C's
    is_valid = True

    for char in s:
        if char == 'A':
            if current_stage > 0:
                is_valid = False
                break
        elif char == 'B':
            if current_stage > 1:
                is_valid = False
                break
            current_stage = max(current_stage, 1)
        elif char == 'C':
            current_stage = max(current_stage, 2)

    if is_valid:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
