def solve(wordsContainer, wordsQuery):
    class TrieNode:
        def __init__(self):
            self.children = {}
            # We store the best index found for this specific suffix path.
            # "Best" is defined by: shortest length, then earliest index.
            self.best_index = -1

    root = TrieNode()

    # Helper to update the best index in a node
    def update_best(node, container_idx):
        if node.best_index == -1:
            node.best_index = container_idx
            return

        current_best_idx = node.best_index
        if len(wordsContainer[container_idx]) < len(wordsContainer[current_best_idx]):
            node.best_index = container_idx
        elif len(wordsContainer[container_idx]) == len(wordsContainer[current_best_idx]):
            if container_idx < current_best_idx:
                node.best_index = container_idx

    # Build the Trie using reversed words (to handle suffixes as prefixes)
    for i, word in enumerate(wordsContainer):
        current = root
        # Update root for the case where there is no common suffix (empty suffix)
        update_best(current, i)

        for char in reversed(word):
            if char not in current.children:
                current.children[char] = TrieNode()
            current = current.children[char]
            update_best(current, i)

    ans = []
    for query in wordsQuery:
        current = root
        best_found_idx = root.best_index

        # Traverse the Trie with the reversed query to find the longest suffix match
        for char in reversed(query):
            if char in current.children:
                current = current.children[char]
                best_found_idx = current.best_index
            else:
                break

        ans.append(best_found_idx)

    return ans
