import math

def findKthSmallestAmount(coins, k):
    def count_amounts(mid):
        # Inclusion-Exclusion Principle to count multiples of any number in coins up to mid
        # For a subset of coins, the number of multiples of their LCM up to mid is floor(mid / LCM)
        n = len(coins)
        count = 0
        # Iterate through all non-empty subsets (2^n - 1 subsets)
        for i in range(1, 1 << n):
            lcm_val = 1
            bits_set = 0
            for j in range(n):
                if (i >> j) & 1:
                    bits_set += 1
                    lcm_val = (lcm_val * coins[j]) // math.gcd(lcm_val, coins[j])
                    # If LCM exceeds mid, we can't have any multiples in range [1, mid]
                    if lcm_val > mid:
                        break

            if lcm_val <= mid:
                if bits_set % 2 == 1:
                    count += mid // lcm_val
                else:
                    count -= mid // lcm_val
        return count

    # Binary search for the smallest value x such that count_amounts(x) >= k
    low = 1
    high = min(coins) * k
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_amounts(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
