    B = []
    for i in range(H):
        B.append([int(x) for x in input_data[idx : idx + W]])
        idx += W

    min_ops = float('inf')

    # The operation allows swapping adjacent rows and adjacent columns.
    # This is equivalent to applying a permutation to rows and a permutation to columns.
    # The number of swaps to reach a permutation is the number of inversions.

    # Since H and W are small (up to 5), we can iterate through all permutations of rows and columns.
    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))

    for rp in row_perms:
        for cp in col_perms:
            # Check if grid A with permutation rp (rows) and cp (cols) equals grid B
            # A[rp[i]][cp[j]] should be B[i][j]
            possible = True
