                    if A[rp[i]][cp[j]] != B[i][j]:
                        possible = False
                        break
                if not possible:
                    break

            if possible:
                # Total operations = inversions in row permutation + inversions in col permutation
                ops = count_inversions(rp) + count_inversions(cp)
                if ops < min_ops:
                    min_ops = ops

