def minimumOperations(nums, k):
    nums.sort()
    n = len(nums)
    # The median is the element at index n // 2 for the given definition
    median_idx = n // 2

    ops = 0
    # If current median is smaller than k, we must increase it and all subsequent 
    # elements that are smaller than k to maintain the sorted property for the median.
    if nums[median_idx] < k:
        for i in range(median_idx, n):
            if nums[i] < k:
                ops += k - nums[i]
            else:
                # Since the array is sorted, once we hit an element >= k, we stop.
                break
    # If current median is larger than k, we must decrease it and all preceding 
    # elements that are larger than k.
    elif nums[median_idx] > k:
        for i in range(median_idx, -1, -1):
            if nums[i] > k:
                ops += nums[i] - k
            else:
                # Since the array is sorted, once we hit an element <= k, we stop.
                break

    return ops
