import sys
from collections import deque

def solve():
    # Read H, W, T
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start_pos = None
    goal_pos = None
    candies = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start_pos = (r, c)
            elif char == 'G':
                goal_pos = (r, c)
            elif char == 'o':
                candies.append((r, c))

    # List of points of interest: Start, Goal, and Candies
    nodes = [start_pos, goal_pos] + candies
    num_nodes = len(nodes)
    dist_matrix = [[float('inf')] * num_nodes for _ in range(num_nodes)]

    def bfs(start_node_idx):
        sr, sc = nodes[start_node_idx]
        dists = [[float('inf')] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == float('inf'):
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for i in range(num_nodes):
            tr, tc = nodes[i]
            dist_matrix[start_node_idx][i] = dists[tr][tc]

    for i in range(num_nodes):
        bfs(i)

    num_candies = len(candies)
    # DP state: dp[mask][last_candy_idx] = min distance
    # mask is a bitmask of visited candies
    # last_candy_idx ranges from 0 to num_candies-1
    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Initialize DP from start node (index 0) to each candy
    for i in range(num_candies):
        d = dist_matrix[0][i + 2]
        if d <= T:
            dp[1 << i][i] = d

    # Fill DP table
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] == float('inf'):
                continue

            curr_dist = dp[mask][i]
            # Try moving to another candy
            for j in range(num_candies):
                if not (mask & (1 << j)):
                    new_dist = curr_dist + dist_matrix[i + 2][j + 2]
                    if new_dist < dp[mask | (1 << j)][j]:
                        dp[mask | (1 << j)][j] = new_dist

    max_candies = -1

    # Check if starting node can reach goal directly
    if dist_matrix[0][1] <= T:
        max_candies = 0

    # Check combinations of candies and then to goal
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i] != float('inf'):
                total_dist = dp[mask][i] + dist_matrix[i + 2][1]
                if total_dist <= T:
                    # count set bits in mask
                    count = bin(mask).count('1')
                    if count > max_candies:
                        max_candies = count

    print(max_candies)

if __name__ == "__main__":
    solve()
