    # Generate all possible prefixes for every number in arr1
    for num in arr1:
        s_num = str(num)
        for i in range(1, len(s_num) + 1):
            prefixes.add(s_num[:i])

    max_len = 0

    # Check every possible prefix for every number in arr2
    for num in arr2:
        s_num = str(num)
        for i in range(1, len(s_num) + 1):
            prefix = s_num[:i]
            if prefix in prefixes:
                max_len = max(max_len, len(prefix))
            else:
                # Since we are checking prefixes from shortest to longest,
                # if the current prefix is not in the set, 
                # no longer prefix of this number will be in the set.
                break

    return max_len
