def isGoodArray(nums):
    # n is the maximum element in the array
    n = max(nums)

    # The length of base[n] is always n + 1
    if len(nums) != n + 1:
        return False

    # Count the occurrences of each number in the array
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    # For the array to be a permutation of base[n]:
    # 1. It must contain numbers from 1 to n
    # 2. Numbers 1 to n-1 must appear exactly once
    # 3. Number n must appear exactly twice
    for i in range(1, n):
        if counts.get(i, 0) != 1:
            return False

    if counts.get(n, 0) != 2:
        return False

    return True
