def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        # Base case: if the string is empty and target is 0, we found a valid partition
        if not s:
            return target == 0
        # If target becomes negative, this path is invalid
        if target < 0:
            return False

        # Try partitioning the string at every possible position
        for i in range(1, len(s) + 1):
            num = int(s[:i])
            if can_partition(s[i:], target - num):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_str = str(i * i)
        if can_partition(square_str, i):
            total_punishment += i * i

    return total_punishment
