import heapq

def minimumCost(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # There are only 26 lowercase English letters.
    # We can use the Floyd-Warshall algorithm or Dijkstra's to find the 
    # shortest path between all pairs of characters.
    # Since there are only 26 nodes, Floyd-Warshall is O(26^3), which is very efficient.

    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    for i in range(26):
        dist[i][i] = 0

    for u_char, v_char, c in zip(original, changed, cost):
        u = ord(u_char) - ord('a')
        v = ord(v_char) - ord('a')
        if c < dist[u][v]:
            dist[u][v] = c

    # Floyd-Warshall algorithm
    for k in range(26):
        for i in range(26):
            if dist[i][k] == inf:
                continue
            for j in range(26):
                if dist[k][j] < inf:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    for s, t in zip(source, target):
        if s == t:
            continue

        u = ord(s) - ord('a')
        v = ord(t) - ord('a')

        if dist[u][v] == inf:
            return -1

        total_cost += dist[u][v]

    return total_cost
