def smallestBeautifulString(s: str, k: int) -> str:
    n = len(s)
    min_len = float('inf')
    best_substring = ""

    # Use a sliding window or nested loop to find all substrings with exactly k ones
    # Since constraints are small (n <= 100), O(n^2) is acceptable
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            if ones_count == k:
                current_substring = s[i:j+1]
                current_len = len(current_substring)

                if current_len < min_len:
                    min_len = current_len
                    best_substring = current_substring
                elif current_len == min_len:
                    if current_substring < best_substring:
                        best_substring = current_substring
                # Once we hit k ones, increasing j will only increase length,
                # so we can break the inner loop for this starting index i.
                break
            elif ones_count > k:
                break

    return best_substring
