        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # Grid to track occupied cells
    grid = [[False for _ in range(W)] for _ in range(H)]

    def find_empty():
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    def backtrack(used_mask):
        empty_pos = find_empty()
        if empty_pos is None:
            return True

        r, c = empty_pos

        # Try every available tile
        for i in range(N):
            if not (used_mask & (1 << i)):
                # Try both orientations of the tile
                for h, w in {(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])}:
                    if can_place(r, c, h, w):
                        place(r, c, h, w, True)
                        if backtrack(used_mask | (1 << i)):
                            return True
                        place(r, c, h, w, False)
        return False

