def minimumBeautifulSubstrings(s: str) -> int:
    def is_beautiful(sub: str) -> bool:
        # No leading zeros allowed
        if sub[0] == '0':
            return False
        # Convert binary string to integer
        val = int(sub, 2)
        # Check if the value is a power of 5
        if val == 0:
            return False
        while val > 1:
            if val % 5 != 0:
                return False
            val //= 5
        return val == 1

    n = len(s)
    # dp[i] stores the minimum number of beautiful substrings for s[0...i-1]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            # Try partitioning from j to i-1
            substring = s[j:i]
            if is_beautiful(substring):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n] if dp[n] != float('inf') else -1
