def solve():
    # Read H, W, K from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    K = int(input_data[2])
    grid = input_data[3:]

    min_ops = float('inf')

    # Check all possible horizontal segments of length K
    for i in range(H):
        row = grid[i]
        # Slide a window of size K across the row
        # To optimize for large grids, we can use a sliding window approach
        # current_x counts 'x' in the window, current_dot counts '.'
        current_x = 0
        current_dot = 0

        for j in range(W):
            # Add new element to window
            char_in = row[j]
            if char_in == 'x':
                current_x += 1
            elif char_in == '.':
                current_dot += 1

            # Remove old element from window
            if j >= K:
                char_out = row[j - K]
                if char_out == 'x':
                    current_x -= 1
                elif char_out == '.':
                    current_dot -= 1

            # If window size is K and there are no 'x's, it's a candidate
            if j >= K - 1:
                if current_x == 0:
                    if current_dot < min_ops:
                        min_ops = current_dot

    # Check all possible vertical segments of length K
    for j in range(W):
        current_x = 0
        current_dot = 0

        for i in range(H):
            # Add new element to window
            char_in = grid[i][j]
            if char_in == 'x':
                current_x += 1
            elif char_in == '.':
                current_dot += 1

            # Remove old element from window
            if i >= K:
                char_out = grid[i - K][j]
                if char_out == 'x':
                    current_x -= 1
                elif char_out == '.':
                    current_dot -= 1

            # If window size is K and there are no 'x's, it's a candidate
            if i >= K - 1:
                if current_x == 0:
                    if current_dot < min_ops:
