import math

def canVisitAll(nums):
    n = len(nums)
    if n == 1:
        return True

    # Union-Find data structure to group connected indices
    parent = list(range(n))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # Map each prime factor to the index of the first number encountered with that factor
    prime_to_index = {}

    for i, val in enumerate(nums):
        if val == 1:
            return False # A 1 cannot have gcd > 1 with any other number

        temp = val
        d = 2
        # Standard prime factorization
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all elements belong to the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
