def getSmallestString(s: str, k: int) -> str:
    def get_dist(c1, c2):
        # Calculate the cyclic distance between two lowercase letters
        d = abs(ord(c1) - ord(c2))
        return min(d, 26 - d)

    n = len(s)
    res = list(s)

    for i in range(n):
        # Try replacing the character at index i with 'a', 'b', ..., 'z'
        # Since we want the lexicographically smallest string, we check 'a' first.
        for char_code in range(ord('a'), ord('z') + 1):
            target_char = chr(char_code)
            cost = get_dist(s[i], target_char)

            # If we can afford this change, we make it and move to the next position
            if k >= cost:
                k -= cost
                res[i] = target_char
                break

    return "".join(res)
