def nspecialPermutations(nums):
    n = len(nums)
    MOD = 10**9 + 7

    # Precompute divisibility to avoid repeated modulo operations
    # adj[i] contains indices j such that nums[i] and nums[j] can be adjacent
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                adj[i].append(j)
                adj[j].append(i)

    # dp[mask][last_idx]
    # mask: bitmask representing the set of visited elements
    # last_idx: the index of the last element added to the permutation
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: permutations of length 1
    for i in range(n):
        dp[1 << i][i] = 1

    # Iterate through all possible masks
    for mask in range(1, 1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            if dp[mask][last] == 0:
                continue

            # Try adding a new element next to 'last'
            for neighbor in adj[last]:
                if not (mask & (1 << neighbor)):
                    new_mask = mask | (1 << neighbor)
                    dp[new_mask][neighbor] = (dp[new_mask][neighbor] + dp[mask][last]) % MOD

    # The answer is the sum of all dp[full_mask][i] for all possible last elements i
    full_mask = (1 << n) - 1
    return sum(dp[full_mask]) % MOD
