import sys
from itertools import permutations

def solve():
    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    r_str = input_data[1]
    c_str = input_data[2]

    # The constraints on N are very small (3 to 5).
    # We can use backtracking to fill the grid.
    # grid[i][j] will be 'A', 'B', 'C', or '.'
    grid = [['.' for _ in range(n)] for _ in range(n)]

    # Tracking characters used in rows and cols
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    def is_valid_so_far(row, col, char):
        if char == '.':
            return True
        if char in row_used[row] or char in col_used[col]:
            return False
        return True

    def check_final_conditions():
        # Check if each row and col has exactly A, B, C
        for i in range(n):
            if len(row_used[i]) != 3: return False
            if len(col_used[i]) != 3: return False

        # Leftmost character in i-th row
        for i in range(n):
            found = False
            for j in range(n):
                if grid[i][j] != '.':
                    if grid[i][j] != r_str[i]:
                        return False
                    found = True
                    break
            if not found: return False

        # Topmost character in j-th col
        for j in range(n):
            found = False
            for i in range(n):
                if grid[i][j] != '.':
                    if grid[i][j] != c_str[j]:
                        return False
                    found = True
                    break
            if not found: return False

        return True

    # Pre-calculate all possible row configurations (N characters, exactly one A, B, C)
    # A row is a tuple of length N.
    possible_rows = []
    chars = ['A', 'B', 'C']
    # To generate all rows: pick 3 positions out of N for A, B, C
    import itertools
    for pos in itertools.combinations(range(n), 3):
        for p in itertools.permutations(chars):
            row = ['.'] * n
            for i in range(3):
                row[pos[i]] = p[i]
            possible_rows.append(tuple(row))

    def backtrack(row_idx):
        if row_idx == n:
            if check_final_conditions():
                return True
            return False

        for row_config in possible_rows:
            # Check if this row config is compatible with column constraints
            possible = True
            for j in range(n):
                char = row_config[j]
                if char != '.' and char in col_used[j]:
                    possible = False
                    break

            if possible:
                # Apply
                for j in range(n):
                    grid[row_idx][j] = row_config[j]
                    if row_config[j] != '.':
                        col_used[j].add(row_config[j])
                row_used[row_idx] = set(['A', 'B', 'C'])

                if backtrack(row_idx + 1):
                    return True

                # Backtrack
                for j in range(n):
                    if row_config[j] != '.':
                        col_used[j].remove(row_config[j])
                row_used[row_idx] = set()

        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print("".join(row))
    else:
        print("No")

